package lk.repairdesk.api.controller; import jakarta.validation.Valid; import lk.repairdesk.api.dto.AuthDtos.*; import lk.repairdesk.api.service.AuthService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService s;public AuthController(AuthService s){this.s=s;}@PostMapping("/register") ResponseEntity<AuthResponse> register(@Valid @RequestBody RegisterRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.register(r));}@PostMapping("/login") AuthResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);}}